B.aCF=new A.qO("\uc0c8\uc1a1\uc774 \ubcd1\uc7ac\ubc30\ub294 \ud759\uc5d0 \ubb3c\uc744 \uc8fc\ub294 \ubc29\uc2dd\uc774 \uc544\ub2c8\uc5d0\uc694. \ubcd1 \uc18d \ubc30\uc9c0\ub294 \uba78\uade0\ud560 \ub54c \ubb3c\uc744 \uba38\uae08\uace0 \uc788\uc5b4\uc11c, \ud0a4\uc6b0\ub294 \ub3d9\uc548\uc5d0\ub294 \ubc29\uc758 \uc2b5\ub3c4\uc640 \u201c\uade0 \uae01\uc740 \uc9c1\ud6c4 \ubb3c\uc8fc\uae30\u201d\ub85c \uad00\ub9ac\ud574\uc694.",B.a7O,"\uc624\uc804(06~11\uc2dc): \ubb3c\uc8fc\uae30\uac00 \ud544\uc694\ud55c \ub0a0(\uade0 \uae01\uc740 \ub0a0)\uc740 \uc624\uc804\uc5d0 \ub9c8\uce58\uace0, \uc2b5\ub3c4\ub97c \ud55c \ubc88 \ub354 \ud655\uc778\ud574\uc694.","\uc624\ud6c4(14~18\uc2dc): \ubc29\uc774 \uac74\uc870\ud574\uc9c0\uae30 \uc26c\uc6b4 \ub54c\uc608\uc694. \uc2b5\ub3c4\uac00 \uae30\uc900 \uc544\ub798\ub85c \ub0b4\ub824\uac00\uba74 \uac00\uc2b5\uc744 \ub298\ub824\uc694.",B.a6T,B.a_1,B.a9f,"\ubb3c\uc758 \uc591\xb7\ud69f\uc218\ub294 \ubcd1 \ud06c\uae30, \ubc29 \ud658\uae30, \uacc4\uc808\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc838\uc694. \u201c\uc790\ub8cc\uc5d0 \uc591\uc774 \uc5c6\uc5b4\uc694\u201d\ub77c\uace0 \uc4f0\uc778 \uce78\uc740 \ud655\uc778\ub41c \uc22b\uc790\uac00 \uc5c6\ub2e4\ub294 \ub73b\uc774\uc5d0\uc694.")
B.TG=new A.bS(8,"\uc624\uc804 8\uc2dc","\uc628\ub3c4\xb7\uc2b5\ub3c4 \ud655\uc778","\uc9c0\uae08 \uc628\ub3c4\xb7\uc2b5\ub3c4(\ub2e8\uacc4\ubcc4 \uae30\uc900\ud45c\uc640 \ube44\uad50)","\uae30\uc900\uc744 \ubc97\uc5b4\ub098\uba74 \uc571\uc758 \u201c\uc2dc\uac04\ub300\ubcc4 \uc628\xb7\uc2b5\ub3c4\u201d \uc870\uce58\ub97c \ub530\ub77c\uc694",B.R,B.q)
B.TK=new A.bS(9,"\uc624\uc804 9\uc2dc","\ud658\uae30\xb7\uacf5\uae30 \ud655\uc778","\ub2f5\ub2f5\ud55c \ub0c4\uc0c8, \uc774\uc0b0\ud654\ud0c4\uc18c \ub18d\ub3c4(\ub18d\ub3c4\uacc4\uac00 \uc788\uc744 \ub54c)","\ub192\uc73c\uba74 \ud658\uae30\ub97c \ub298\ub824\uc694",B.R,B.q)
B.TL=new A.bS(10,"\uc624\uc804 10\uc2dc","\ubcd1 \uad00\ucc30","\uade0\uc774 \ud37c\uc9c4 \uc815\ub3c4\xb7\uc2f9 \uc62c\ub77c\uc628 \uc815\ub3c4\xb7\ub300 \uae38\uc774","\uc0ac\uc9c4\uc744 \ucc0d\uace0 \uae30\ub85d\ud574\uc694",B.R,B.q)
B.U1=new A.bS(14,"\uc624\ud6c4 2\uc2dc","\uc624\uc5fc\xb7\ubb3c\uae30 \uc810\uac80","\uc0c9\uc774 \ub2e4\ub978 \uc5bc\ub8e9, \ubcd1 \uc717\uba74\uc774 \ub9c8\ub974\uac70\ub098 \uace0\uc778 \ubb3c\uc774 \uc788\ub294\uc9c0","\uc5bc\ub8e9 \ubcd1\uc740 \ubd84\ub9ac\ud558\uace0, \ub9c8\ub978 \uba74\uc740 \uba78\uade0\uc218\ub97c \uc918\uc694",B.R,B.q)
B.Tu=new A.bS(21,"\ubc24 9\uc2dc","\ucd5c\uc885 \uc810\uac80","\ubb38\xb7\ucc3d, \ub09c\ubc29\xb7\uac00\uc2b5 \uc124\uc815\uac12, \uc7a5\uce58 \uc54c\ub9bc","\ubc24\uc0c8 \uc720\uc9c0\ud560 \uc124\uc815\uc774 \ub9de\ub294\uc9c0 \ud655\uc778\ud574\uc694",B.R,B.q)
B.a72=s([B.TG,B.TK,B.TL,B.U1,B.us,B.Tu],t.lO)
B.a4C=s(["\uba78\uade0\uc774 \ub35c \ub410\uac70\ub098 \uc811\uc885\ud560 \ub54c \uc7a1\uade0\uc774 \ub4e4\uc5b4\uac14\uc744 \uc218 \uc788\uc5b4\uc694.","\ubc30\uc591\uc2e4 \uc628\ub3c4\uac00 \ub108\ubb34 \ub192\uac70\ub098 \uacf5\uae30\uac00 \uae68\ub057\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.afb=s(["\uc5bc\ub8e9\uc774 \ud55c \ubcd1\ubfd0\uc778\uc9c0 \uc5ec\ub7ec \ubcd1\uc778\uc9c0 \ubd10\uc694.","\uac19\uc740 \ub0a0 \uc811\uc885\ud55c \ubcd1\uc774\ub098 \uac19\uc740 \uc904\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294\uc9c0 \ubd10\uc694.","\ubc30\uc591\uc2e4 \uc628\ub3c4\uac00 20~22\u2103\uc778\uc9c0 \uae30\ub85d\uc744 \ud655\uc778\ud574\uc694."],t.s)
B.aes=s(["\uc624\uc5fc\ub41c \ubcd1\uc740 \ub69c\uaed1\uc744 \uc5f4\uc9c0 \ub9d0\uace0 \ube44\ub2d0\ubd09\uc9c0\uc5d0 \ub2f4\uc544 \ubc16\uc5d0 \ubc84\ub824\uc694(\uacf0\ud321\uc774 \uac00\ub8e8\uac00 \ud37c\uc9c0\uc9c0 \uc54a\uac8c).","\ub0a8\uc740 \ubcd1\uc740 \ub530\ub85c \ub5a8\uc5b4\ub728\ub824 \ub9e4\uc77c \uc9c0\ucf1c\ubd10\uc694."],t.s)
B.Zz=s(["\uba78\uade0 \uc628\ub3c4\xb7\uc2dc\uac04\uc744 \uae30\ub85d\ud574\uc694.","\uc811\uc885\ud560 \ub54c \uc190\uacfc \ub3c4\uad6c\ub97c \uc18c\ub3c5\ud574\uc694.","\ubc30\uc591\uc2e4\uc744 \uc815\uae30\uc801\uc73c\ub85c \uccad\uc18c\ud574\uc694."],t.s)
B.aAT=new A.cf("\ubcd1 \uc18d\uc5d0 \ud478\ub978\uc0c9\xb7\uac80\uc740\uc0c9\xb7\ubd84\ud64d\uc0c9 \uc5bc\ub8e9(\uacf0\ud321\uc774)\uc774 \uc0dd\uaca8\uc694",B.a4C,B.afb,B.aes,B.Zz,B.R,B.q)
B.a8s=s(["\ubc1c\uc774 \uc628\ub3c4\xb7\uc2b5\ub3c4\uac00 \uae30\uc900(14~16\u2103, 90% \uc774\uc0c1)\uc744 \ubc97\uc5b4\ub0ac\uc744 \uc218 \uc788\uc5b4\uc694.","\uade0 \uae01\uc740 \ub4a4 \ud45c\uba74\uc774 \ub9d0\ub790\uc744 \uc218 \uc788\uc5b4\uc694.","\ubc30\uc591\uc774 \ub35c \ub05d\ub09c \ubcd1\uc744 \ubc1c\uc774\ub85c \ub118\uacbc\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.a33=s(["\ubc1c\uc774\uc2e4 \uc628\ub3c4\xb7\uc2b5\ub3c4 \uae30\ub85d\uc744 \ubd10\uc694.","\ubcd1 \uc717\uba74\uc774 \ub9d0\ub790\ub294\uc9c0 \ubd10\uc694.","\ubcd1 \uc804\uccb4\uac00 \ud770 \uade0\uc73c\ub85c \ub36e\uc600\ub294\uc9c0 \ubd10\uc694."],t.s)
B.aeZ=s(["\uc628\ub3c4\ub97c 14~16\u2103, \uc2b5\ub3c4\ub97c 90% \uc774\uc0c1\uc73c\ub85c \ub9de\ucdb0\uc694.","\ub9c8\ub978 \uba74\uc5d0\ub294 \uba78\uade0\uc218\ub97c \uc918\uc694(\uc591\uc740 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694).","\ub35c \ub36e\uc600\uc73c\uba74 \ubc30\uc591\uc2e4\ub85c \ub418\ub3cc\ub824 \uba70\uce60 \ub354 \ud0a4\uc6cc\uc694."],t.s)
B.a35=s(["\ubc30\uc591\uc774 \ub05d\ub09c \uac83\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud55c \ub4a4 \ubc1c\uc774\ub85c \ub118\uaca8\uc694.","\uade0 \uae01\uc740 \uc9c1\ud6c4 \ubc14\ub85c \ubb3c\uc744 \uc918\uc694."],t.s)
B.aB1=new A.cf("\uc2f9(\ubc84\uc12f)\uc774 \uc548 \uc62c\ub77c\uc624\uac70\ub098 \ub108\ubb34 \uc801\uc5b4\uc694",B.a8s,B.a33,B.aeZ,B.a35,B.x,B.ap)
B.a5b=s(["\uc18e\uae30\ub97c \ud558\uc9c0 \uc54a\uc558\uac70\ub098 \ub2a6\uac8c \ud588\uc5b4\uc694."],t.s)
B.a1X=s(["\ubcd1 \ud558\ub098\uc5d0 \uc2f9\uc774 \uba87 \uac1c\uc778\uc9c0 \uc138\uc5b4 \ubd10\uc694.","\ub300 \uae38\uc774\uac00 \uc81c\uac01\uac01\uc778\uc9c0 \ubd10\uc694."],t.s)
B.a5x=s(["\uc2f9\uc774 \uc62c\ub77c\uc628 1~2\uc77c \uc548\uc5d0 \ubcd1\ub2f9 2~3\uac1c\ub9cc \ub0a8\uae30\uace0 \uc18e\uc544\uc694(\uc790\ub8cc \uae30\uc900)."],t.s)
B.a3U=s(["\ubc1c\uc774 \ub2e8\uacc4 \ub9c8\uc9c0\ub9c9 \ub0a0 \u201c\uc18e\uae30\u201d\ub97c \ub2ec\ub825\uc5d0 \ud45c\uc2dc\ud574 \ub450\uc5b4\uc694."],t.s)
B.aAH=new A.cf("\uc2f9\uc774 \ub108\ubb34 \ube7d\ube7d\ud574\uc11c \uc791\uc740 \ubc84\uc12f\ub9cc \uc790\ub77c\uc694",B.a5b,B.a1X,B.a5x,B.a3U,B.m,B.ap)
B.abN=s(["\ud658\uae30\uac00 \ubd80\uc871\ud558\uac70\ub098 \uc2b5\ub3c4\uac00 \ub192\uc744 \uc218 \uc788\uc5b4\uc694(\uc77c\ubc18 \uc694\ub839).","\uc774\uc0b0\ud654\ud0c4\uc18c \ub18d\ub3c4\uac00 \ub192\uc744 \uc218 \uc788\uc5b4\uc694(\ubc1c\uc774 2,000ppm \uc774\ud558, \uc0dd\uc721 1,000~3,000ppm\uc774 \uae30\uc900)."],t.s)
B.a0a=s(["\uc774\uc0b0\ud654\ud0c4\uc18c \ub18d\ub3c4\uacc4 \uc218\uce58\ub97c \ud655\uc778\ud574\uc694.","\uc2b5\ub3c4\uac00 \uae30\uc900(\uc0dd\uc721 80~90%)\uc744 \ub118\ub294\uc9c0 \ubd10\uc694.","\ubc1c\uc774\uc2e4 \ubb38\uc744 \uc624\ub798 \ub2eb\uc544 \ub450\uc9c0 \uc54a\uc558\ub294\uc9c0 \ubd10\uc694."],t.s)
B.ZY=s(["\ud658\uae30\ub97c \ub298\ub824\uc694.","\uc2b5\ub3c4\uac00 \ub192\uc73c\uba74 \uac00\uc2b5\xb7\ubb3c \ubfcc\ub9ac\uae30\ub97c \uc904\uc5ec\uc694."],t.s)
B.ade=s(["\uc0dd\uc721\uc2e4 \ud658\uae30 \uc2dc\uac04\uc744 \uc815\ud574 \ub450\uc5b4\uc694.","\uc774\uc0b0\ud654\ud0c4\uc18c \ub18d\ub3c4\ub97c \ud558\ub8e8 \ud55c \ubc88 \uae30\ub85d\ud574\uc694."],t.s)
B.aAM=new A.cf("\ub300\uac00 \uac00\ub298\uace0 \uae38\uac70\ub098 \uac13\uc774 \uc791\uc544\uc694",B.abN,B.a0a,B.ZY,B.ade,B.x,B.ap)
B.a1c=s(["\uc2b5\ub3c4\uac00 \ub0ae\uc744 \uc218 \uc788\uc5b4\uc694.","\ud658\uae30 \ubc14\ub78c\uc774 \ubc84\uc12f\uc5d0 \uc9c1\uc811 \ub2ff\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aez=s(["\uc2b5\ub3c4 \uae30\ub85d\uc774 80% \uc544\ub798\ub85c \ub0b4\ub824\uac14\ub294\uc9c0 \ubd10\uc694.","\ud658\uae30\uad6c \ubc14\ub78c\uc774 \ubc84\uc12f \ucabd\uc73c\ub85c \ud5a5\ud558\ub294\uc9c0 \ubd10\uc694."],t.s)
B.Z7=s(["\uac00\uc2b5\uc744 \ub298\ub824 \uc2b5\ub3c4\ub97c 80~90%\ub85c \ub9de\ucdb0\uc694.","\ubc14\ub78c \ubc29\ud5a5\uc744 \ubc84\uc12f\uc5d0\uc11c \ub3cc\ub824\uc694."],t.s)
B.a8S=s(["\ud658\uae30 \ub54c \uc2b5\ub3c4\uac00 \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\uc9c0 \ud568\uaed8 \ud655\uc778\ud574\uc694."],t.s)
B.aAY=new A.cf("\uac13\uc774 \uac08\ub77c\uc9c0\uac70\ub098 \uac00\uc7a5\uc790\ub9ac\uac00 \ub9d0\ub77c\uc694",B.a1c,B.aez,B.Z7,B.a8S,B.x,B.ap)
B.adJ=s(["\uc2b5\ub3c4\uac00 \ub108\ubb34 \ub192\uac70\ub098 \ud658\uae30\uac00 \ubd80\uc871\ud560 \uc218 \uc788\uc5b4\uc694.","\ubcd1 \uc704\uc5d0 \ubb3c\uc774 \uace0\uc600\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.a4x=s(["\uc2b5\ub3c4\uac00 \uae30\uc900 \uc704\uc778\uc9c0 \ubd10\uc694.","\ubcd1 \uc717\uba74\uc5d0 \uace0\uc778 \ubb3c\uc774 \uc788\ub294\uc9c0 \ubd10\uc694.","\uc774\uc0c1\ud55c \ub0c4\uc0c8\uac00 \ub098\ub294\uc9c0 \ub9e1\uc544 \ubd10\uc694."],t.s)
B.afA=s(["\ud658\uae30\ub97c \ub298\ub9ac\uace0 \uac00\uc2b5\uc744 \uc904\uc5ec\uc694.","\uace0\uc778 \ubb3c\uc740 \ub2e6\uace0, \uc2ec\ud558\uac8c \ubb3c\ub7ec\uc9c4 \ubc84\uc12f\uc740 \ub530\ub85c \uce58\uc6cc\uc694."],t.s)
B.adM=s(["\uc2b5\ub3c4\ub97c \uae30\uc900 \ubc94\uc704 \uc548\uc5d0\uc11c \uc720\uc9c0\ud574\uc694.","\ubb3c\uc8fc\uae30\ub294 \uade0 \uae01\uc740 \uc9c1\ud6c4\uc5d0\ub9cc \ud574\uc694."],t.s)
B.aB0=new A.cf("\ubc84\uc12f\uc774 \ubb3c\ub7ec\uc9c0\uace0 \ub048\uc801\ud574\uc694",B.adJ,B.a4x,B.afA,B.adM,B.R,B.q)
B.a9S=s(["\uc628\ub3c4\uac00 \uae30\uc900\ubcf4\ub2e4 \ub0ae\uc744 \uc218 \uc788\uc5b4\uc694(\ubc1c\uc774\xb7\uc0dd\uc721 14~16\u2103).","\ubcd1 \ud06c\uae30\ub098 \ud488\uc885\uc774 \uc790\ub8cc\uc640 \ub2e4\ub97c \uc218 \uc788\uc5b4\uc694."],t.s)
B.abI=s(["\ub2e8\uacc4\ubcc4 \uc628\ub3c4 \uae30\ub85d\uc744 \ubd10\uc694.","\uc0ac\uc6a9 \uc911\uc778 \ubcd1 \ud06c\uae30(850ml\uc778\uc9c0)\uc640 \ud488\uc885\uc744 \ud655\uc778\ud574\uc694."],t.s)
B.abM=s(["\uc628\ub3c4\uac00 \ub0ae\uc73c\uba74 \ub09c\ubc29\uc744 \uc870\uae08 \uc62c\ub824\uc694. \uac11\uc790\uae30 \uc62c\ub9ac\uc9c0\ub294 \uc54a\uc544\uc694.","\ud488\uc885\xb7\ubcd1 \ud06c\uae30\uac00 \ub2e4\ub974\uba74 \ub18d\uc5c5\uae30\uc220\uc13c\ud130\uc5d0\uc11c \uadf8 \ud488\uc885\uc758 \uae30\uc900\uc744 \ud655\uc778\ud574\uc694."],t.s)
B.a7b=s(["\uc628\ub3c4\uacc4\ub97c \ubcd1 \ub192\uc774\uc5d0 \ub450\uace0 \ud558\ub8e8 3\ubc88 \uae30\ub85d\ud574\uc694."],t.s)
B.aAI=new A.cf("\uc790\ub77c\ub294 \uc18d\ub3c4\uac00 \ub108\ubb34 \ub290\ub824\uc694",B.a9S,B.abI,B.abM,B.a7b,B.x,B.ap)
B.a6s=s([B.aAT,B.aB1,B.aAH,B.aAM,B.aAY,B.aB0,B.aAI],t.oE)
B.SY=new A.mW("king-oyster","\uc0c8\uc1a1\uc774\ubc84\uc12f","\ubc84\uc12f","\ubcd1\uc5d0 \ud0a4\uc6b0\ub294 \ubc84\uc12f. \uc811\uc885\ubd80\ud130 \uc218\ud655\uae4c\uc9c0 \uc57d 50~60\uc77c(\uc790\ub8cc \ud45c\uae30)","850ml \ubcd1\uc7ac\ubc30(\ud070\ub290\ud0c0\ub9ac, \ub18d\uc0ac\ub85c \uc601\uc0c1 \uae30\uc900). \ubcd1\uc5d0 \ubc30\uc9c0\ub97c \ub123\uc5b4 \uba78\uade0\xb7\uc811\uc885\ud55c \ub4a4 \ubc30\uc591\uc2e4 \u2192 \ubc1c\uc774 \u2192 \uc0dd\uc721 \uc21c\uc11c\ub85c \ud0a4\uc6cc\uc694.",B.m,B.ap,"\uc811\uc885\uc77c","\uc885\uade0(\uc528\uc557 \uc5ed\ud560\uc744 \ud558\ub294 \uade0)\uc744 \ubcd1\uc5d0 \ub123\uc740 \ub0a0\uc744 \uc785\ub825\ud574\uc694. \ubc30\uc591\uc774 \ub05d\ub09c \ubcd1\uc744 \uc0ac \uc654\ub2e4\uba74 \ubc1b\uc740 \ub0a0\uc744 \uc785\ub825\ud558\uace0, \ud604\uc7ac \ub2e8\uacc4\ub97c \u2018\ubc1c\uc774\u2019\ub85c \ubc14\uafd4 \uc8fc\uc138\uc694.",B.ac7,B.adg,B.aam,B.acj,B.pX,B.aCF,B.a72,B.a6s)
