B.acB=s(["\uc2b5\ub3c4\uac00 \ub192\uace0 \ud658\uae30\uac00 \ubd80\uc871\ud560 \uc218 \uc788\uc5b4\uc694.","\uc78e\uc774 \uc816\uc740 \ucc44\ub85c \ubc24\uc744 \ubcf4\ub0c8\uc744 \uc218 \uc788\uc5b4\uc694.","\ud3ec\uae30\uac00 \ub108\ubb34 \ube7d\ube7d\ud560 \uc218 \uc788\uc5b4\uc694."],t.s)
B.a8z=s(["\ud658\uae30 \uc2dc\uac04\uacfc \uc2b5\ub3c4 \uae30\ub85d\uc744 \ubd10\uc694.","\ud3ec\uae30 \ubc11\ub3d9\uc5d0 \ubb3c\uc774 \uace0\uc600\ub294\uc9c0 \ubd10\uc694.","\uc0c1\ucd94\uc5d0\uc11c \ud754\ud55c \ubcd1: \ub178\uade0\ubcd1\xb7\uade0\ud575\ubcd1\xb7\uc7bf\ube5b\uacf0\ud321\uc774\xb7\ubb34\ub984\ubcd1\uc774\uc5d0\uc694(\uc790\ub8cc)."],t.s)
B.aed=s(["\ubcd1\ub4e0 \uc78e\xb7\ud3ec\uae30\ub294 \ub530\ub85c \ub72f\uc5b4 \ubc16\uc5d0 \ubc84\ub824\uc694.","\ud658\uae30\ub97c \ub298\ub824\uc694.","\ub18d\uc57d\uc740 \ub4f1\ub85d\ub41c \uc57d\uc81c\ub9cc \uc548\uc804\uc0ac\uc6a9\uae30\uc900\uc5d0 \ub9de\uac8c \uc368\uc57c \ud574\uc694. \ubaa8\ub974\uba74 \ub18d\uc5c5\uae30\uc220\uc13c\ud130\uc5d0 \ubb38\uc758\ud574\uc694(\uc790\ub8cc)."],t.s)
