B.SJ=new A.e0("grow","\uc0dd\uc721","\uc2f9\uc774 \uc62c\ub77c\uc640 \uc78e\uacfc \uc904\uae30, \ubfcc\ub9ac\uac00 \uc790\ub77c\ub294 \ub2e8\uacc4",22,57,B.x,B.lR,"\uc815\uc2dd \ud6c4 \ucd1d 25\uc77c(\ub2e4\ub978 \ub18d\uac00 \uc0ac\ub840 25~30\uc77c)\uc5d0\uc11c 60\uc77c(\ud55c \ub18d\uac00 \uc0ac\ub840)\uae4c\uc9c0\ub85c \uc0ac\ub840\uac00 \ub2ec\ub77c \ub113\uac8c \uc7a1\uc558\uc5b4\uc694. \ub17c\ubb38 \uc2e4\ud5d8\uc740 21\uc77c \uc2dc\uc810\uc5d0 \uce21\uc815\ud588\uc5b4\uc694. \uc6d0\ud558\ub294 \ud06c\uae30\uac00 \ub418\uba74 \uc218\ud655\uae30\ub85c \ub118\uaca8 \uc8fc\uc138\uc694.",!1)
B.SN=new A.e0("harvest","\uc218\ud655","\uc6d0\ud558\ub294 \ud06c\uae30\uac00 \ub41c \uc0c8\uc2f9\uc0bc\uc744 \ubf51\uc544 \uc53b\uc5b4 \ub0b4\ub294 \ub2e8\uacc4",null,null,B.ao,B.q,"\uc218\ud655 \ud06c\uae30 \uae30\uc900\uacfc \uac78\ub9ac\ub294 \uc77c\uc218\ub294 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694.",!1)
